window.FILM_WORK_PROMPTS={"work_id":"src-535030206809c3fc","records":[{"work_id":"src-535030206809c3fc","frame_id":"FG-ab11f5bdcf6b16bd","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1212).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"一位留着灰白胡须的年长男性，头戴金色双角头盔，身穿黑金相间的金属铠甲，右手紧握一根金色长杆，背景为模糊的浅褐色纹理。","analysis":"画面采用近景构图，人物占据画面右侧及中心大部分区域，头部与肩部清晰可见。视角略微仰视，突显人物的威严感。光线柔和，金色头盔与铠甲反射出金属光泽，与面部苍白的肤色及灰白胡须形成对比。背景虚化处理，色调统一为暖褐色，使主体更加突出。","prompt":"一位年长男性角色的近景画面，面部可见，留着浓密的灰白胡须，神情严肃。他头戴复杂的金色双角头盔，头盔表面光滑，反射着环境光。身穿黑金配色的金属铠甲，肩部有圆形的金色护甲片。人物右手紧握一根垂直的金色长杆，位于画面左侧。背景是高度虚化的浅褐色纹理，呈现出类似编织物或岩石的质感，色调温暖统一。整体光影柔和，金属质感强烈，画面具有电影般的质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:03-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (1212).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.535,"observed_resolution":"normal","observation_limits":[],"id":"VP-7a84f06d49c5cc3d","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-ab7b884485cad7bf","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1237).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"一位戴棒球帽、留灰白胡须的年长男性，身穿深色厚外套，站立于画面中央。背景为大面积泛黄的浑浊天空与云层，人物占据画面主体。","analysis":"采用仰视视角拍摄，人物上半身及头部清晰可见，占据画面中心位置。背景天空占据约70%画面比例，云层厚重且呈暖黄色调。光线柔和漫射，无强烈阴影，整体色调统一为土黄与深褐，人物面部受光均匀，轮廓在明亮背景下清晰可辨。","prompt":"仰视视角，一位年长男性站立于画面中央，头戴深色棒球帽，面部留有灰白胡须，神情严肃。身穿深褐色厚重夹克外套，内搭深色衣物。背景为大面积泛黄的浑浊天空，云层厚重且呈暖色调，光线柔和漫射。人物占据画面主体，天空环境占比约七成，整体色调统一为土黄与深褐，无强烈阴影，呈现出一种压抑而温暖的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:10-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (1237).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.493,"observed_resolution":"normal","observation_limits":[],"id":"VP-adf5728be8ecb6fd","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-9b07d872ddf2fda2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1234).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"夜间俯瞰视角下的荒野工地，中心矗立着由发光白色管道构成的巨大环形与十字交叉结构，周围散布着临时板房、车辆及照明设备。","analysis":"画面采用高空垂直俯视构图，主体为占据画面中心的大型发光装置，呈不规则环形与十字形布局。环境为昏暗的泥土地面，周围分布着零星的蓝色板房和深色车辆。光源主要来自装置本身的白色冷光及周边的几盏高杆照明灯，形成强烈的明暗对比，整体色调偏冷绿与暗黄。","prompt":"这是一张夜间高空垂直俯瞰的广角画面，展示了一个位于荒野泥土地面上的大型实验装置。画面中心是由白色发光管道组成的巨大环形结构，管道呈分段状，连接成一个不规则的圆环，并在中心位置通过十字交叉的管道连接到一个方形框架结构。装置周围散布着几座蓝色的临时板房、深色的车辆以及施工设备。几盏高杆照明灯矗立在场地边缘，投射出冷白色的光束，照亮了部分地面。整体环境昏暗，地面呈现深褐色与暗绿色调，与中心装置发出的明亮白光形成强烈对比，营造出一种神秘且工业化的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:18-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (1234).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.51,"observed_resolution":"normal","observation_limits":[],"id":"VP-a19b5471a318bef6","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-41cf75b478285b31","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1209).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"昏暗室内，两名男子并排坐在桌前，左侧男子手持深色酒瓶，右侧男子双手置于桌面，背景是发着粉绿霓虹光的玻璃砖墙，右上角有蓝色“MEN”字样。","analysis":"画面截取人物上半身，两人占据画面左右两侧，中间留有空间。背景玻璃砖墙呈现明显的粉色与青绿色霓虹光带，与前景人物的暗部形成强烈对比。光线主要来自背景，在人物面部和肩部形成轮廓光，整体色调偏冷且对比度高，营造出一种私密且略带压抑的氛围。","prompt":"昏暗酒吧或休息室环境，两名男子并排坐在深色桌前。左侧男子发际线较高，身穿深色外套，右手握着一瓶深色玻璃瓶；右侧男子留着金色长发和络腮胡，身穿深色衬衫内搭灰色T恤，双手自然放在桌面上。两人中间放着一个装有浅色零食的透明玻璃碗。背景是一面玻璃砖墙，透出明亮的粉色和青绿色霓虹灯光，右上角可见模糊的蓝色“MEN”霓虹招牌。整体光线昏暗，主要光源来自背景霓虹，人物面部处于阴影中，呈现出高对比度的冷色调视觉效果。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:25-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (1209).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.514,"observed_resolution":"normal","observation_limits":[],"id":"VP-4f6a854ab648f704","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-11282f6eae71406b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (1109).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"画面左侧为一张黑色粗糙质感的侧脸，眼部有微弱红光，背景为大面积模糊的暖黄褐色色块。","analysis":"构图极度偏左，人物面部占据画面左半部分，右侧为大面积留白。仅可见人物头部侧面轮廓，包括额头、鼻梁、嘴唇及下巴。光线从右侧打入，勾勒出面部边缘的起伏与纹理，整体处于暗部，仅眼部有一点红色反光，背景为均匀的暖色调。","prompt":"画面左侧是一个黑色、表面粗糙如岩石或皮革质感的侧脸特写，面部轮廓在暗部中显现，鼻梁高挺，嘴唇紧闭，皮肤表面有细微的颗粒感。眼部位置有一点微弱的红色亮光。画面右侧约二分之一区域为模糊的暖黄褐色背景，光线柔和且均匀，没有具体物体细节。整体光影对比强烈，人物面部大部分处于阴影中，仅边缘受光，营造出一种神秘、压抑且充满质感的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:02:32-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (1109).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.533,"observed_resolution":"normal","observation_limits":[],"id":"VP-993f573b99b220a8","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-6cc15017abced734","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (1212).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"金发男子侧脸特写，面带微笑，背景为模糊的暖色人群。","analysis":"画面采用极浅景深，焦点完全集中在人物面部，背景虚化为柔和的暖色光斑。人物占据画面左侧约三分之一，呈现清晰的右侧脸轮廓，可见金发、胡须及嘴角上扬的微笑。光线从右前方照射，在面部形成强烈的明暗对比，高光集中在额头、鼻梁和脸颊，阴影深邃，营造出温暖而戏剧化的氛围。","prompt":"这是一张高清晰度的男性侧脸特写。画面主体为一名留着金色中长发的男子，头发自然垂落至颈部，面部留有修剪整齐的络腮胡。他面朝右侧，嘴角上扬露出牙齿，神情愉悦。光线从右侧打入，照亮了他的额头、鼻梁和脸颊，形成鲜明的明暗交界线，皮肤质感细腻。背景完全失焦，呈现出模糊的暖黄色调，隐约可见其他人物的轮廓，营造出一种热闹而温暖的现场感。人物肩部可见深色衣物及红色边缘，整体色调偏暖，具有强烈的电影质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:32:45+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (1212).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.531,"observed_resolution":"normal","observation_limits":[],"id":"VP-f6ce5eb98813dfd4","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-b0dff030a6a07e93","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (1237).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"绿色路牌占据画面左侧前景，背景为黄昏时分的加油站建筑、停放的车辆、电线杆与枯黄草地，天空呈现暖色调。","analysis":"路牌位于左侧前景，呈倾斜角度，占据画面约三分之一宽度，文字清晰可见。背景加油站建筑位于右侧中景，包含红绿条纹遮阳棚和白色立柱，两辆汽车停放在建筑旁。画面采用低角度仰拍，路牌边缘锐利，背景略微虚化。光线来自右上方，呈现黄昏暖黄色调，天空由浅蓝过渡至橙黄，整体明暗对比柔和。","prompt":"黄昏时分的公路场景，左侧前景是一块倾斜的绿色矩形路牌，白色文字写着Puente Antiguo CITY LIMIT POP 2,175 ELEV 6,056，路牌边缘有白色边框。背景右侧是一座加油站建筑，带有红绿相间的条纹遮阳棚和白色支撑柱，建筑旁停放着一辆深色皮卡车和一辆银色轿车。远处可见电线杆和枯黄的草地，天空呈现从浅蓝到橙黄的渐变暖色调，整体画面带有电影质感的暖黄色光晕，路牌清晰锐利，背景略微柔和。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:32:53+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (1237).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.504,"observed_resolution":"normal","observation_limits":[],"id":"VP-41e3d990e8219f52","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-91fd3e1ae7c98321","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (1234).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"昏暗的监控室内，一名男子坐在电脑前操作，身后站着一名戴墨镜的男子，背景有垂直发光条和远处人影。","analysis":"画面主体为前景坐着的男子，其上半身及双手可见，正面对屏幕。中景站立男子仅上半身可见，戴墨镜。背景有垂直白色光条和模糊人影。构图采用侧向视角，前景显示器占据左侧，人物位于右侧。光线昏暗，主要光源来自屏幕蓝光和背景垂直白光，形成冷色调对比，人物面部受屏幕光映照。","prompt":"昏暗的室内监控中心场景，前景右侧一名深色短发男子身穿白衬衫和深色马甲，坐在桌前，双手置于键盘上，面部朝向左侧的电脑屏幕，神情专注。左侧前景是一台显示着复杂数据界面的电脑显示器，屏幕发出冷青色光芒。中景处，一名戴墨镜、穿深色西装的男子站立在后方，身体略微前倾。背景是深邃的黑暗空间，右侧有垂直排列的白色发光灯条，远处隐约可见其他站立的人影。整体色调偏冷，以黑色、深蓝色和屏幕的青光为主，光影对比强烈，营造出紧张、高科技的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:33:01+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (1234).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.463,"observed_resolution":"normal","observation_limits":[],"id":"VP-3c1930b2fbfc0684","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-d29eb8110f464e0e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (1202).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"夜间户外碎石地面，两人并排坐于躺椅上，左侧有燃烧的火盆，右侧背景矗立着带有青色霓虹灯带和发光字母的圆形建筑结构。","analysis":"画面采用平视视角，构图横向展开。前景为碎石地面，中景两人并排而坐，左侧人物穿浅色上衣，右侧人物穿红黑格纹衬衫，均可见上半身及腿部。左侧火盆火焰明亮，右侧背景建筑发出青绿色霓虹光，与黑色夜空形成冷暖对比。","prompt":"夜间户外场景，地面铺满灰色碎石。画面左侧前景放置一个黑色圆形金属火盆，内部燃烧着明亮的橙黄色火焰。火盆右侧，两名人物并排坐在带有金属支架的软垫躺椅上，左侧人物身穿米色长袖上衣，右侧人物身穿红黑格纹衬衫，两人均呈坐姿，身体朝向左侧。画面右侧背景是一座巨大的圆形建筑结构，边缘环绕着多层青绿色霓虹灯带，上方竖立着发光的白色字母装置。背景天空漆黑，远处可见零星微弱灯光，整体光影由火盆暖光与建筑冷光交织构成。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:33:08+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (1202).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.566,"observed_resolution":"normal","observation_limits":[],"id":"VP-97768f693d1dc9e0","origin":"visual"},{"work_id":"src-535030206809c3fc","frame_id":"FG-7220d31ef0c126dc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (1096).jpg","source_page":"https://film-grab.com/2015/01/05/thor/","scene":"一名金发男子身穿深色铠甲与红色披风，手持方形锤状物，站立在倾斜的木质结构边缘，背景为布满星点的黑色夜空。","analysis":"画面采用仰视视角，主体人物占据画面右侧及中央大部分区域，全身可见。左侧为倾斜的木质纹理结构，与人物形成对角线构图。人物面部及身体受光，与黑暗背景形成强烈明暗对比，红色披风在暗色环境中色彩饱和度高，视觉焦点集中。","prompt":"仰视视角，一名金发男子身穿深色金属铠甲，身披鲜红色长披风，右手持握方形锤状物，站立在倾斜的木质结构边缘。背景为深邃的黑色星空，散布着稀疏的星点。人物全身可见，姿态挺拔，面部受光清晰，红色披风在暗色背景下显得格外醒目，左侧木质结构纹理粗糙，与人物形成空间对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:33:15+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (1096).jpg","observed_dimensions":[1280,544],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.476,"observed_resolution":"normal","observation_limits":[],"id":"VP-6d6c3dfeb775713d","origin":"visual"}]};